Inductive Bytes :=
| BytesList : MaterializedBytes -> Bytes
| BytesSlice : ByteSlice -> Bytes.
Arguments Bytes : clear implicits.

Definition sail_Bytes_encode (x : Bytes) := match x with
  | BytesList x' => encode (0, encode x')
  | BytesSlice x' => encode (1, encode x') end.
Definition sail_Bytes_decode x : option Bytes := match decode x with
  | Some (0, x') => BytesList <$> decode x'
  | Some (1, x') => BytesSlice <$> decode x'
  | _ => None end.
Lemma sail_Bytes_decode_encode : forall (x : Bytes), sail_Bytes_decode (sail_Bytes_encode x)
   = Some x.
Proof.
  unfold sail_Bytes_decode, sail_Bytes_encode;
  intros [x|x]; rewrite !decode_encode; reflexivity.
Qed.

#[export]
Instance Decidable_eq_Bytes : EqDecision Bytes := decode_encode_eq_dec sail_Bytes_encode
  sail_Bytes_decode sail_Bytes_decode_encode .

#[export]
Instance Countable_Bytes : Countable Bytes := {|
  encode := sail_Bytes_encode;
  decode := sail_Bytes_decode;
  decode_encode := sail_Bytes_decode_encode
|}.
#[export]
Instance dummy_Bytes : Inhabited (Bytes) := { inhabitant := BytesList inhabitant }.

Inductive ExceptionKind :=
  | StackUnderflow
  | StackOverflow
  | OutOfGas
  | InvalidOpcode
  | InvalidJump
  | StaticViolation
  | CallDepthExceeded
  | InsufficientBalance
  | WriteProtection
  | InitCodeTooLarge
  | NonceOverflow
  | AddressCollision.
Definition num_of_ExceptionKind (arg_ : ExceptionKind) : Z :=
   match arg_ with
   | StackUnderflow => 0
   | StackOverflow => 1
   | OutOfGas => 2
   | InvalidOpcode => 3
   | InvalidJump => 4
   | StaticViolation => 5
   | CallDepthExceeded => 6
   | InsufficientBalance => 7
   | WriteProtection => 8
   | InitCodeTooLarge => 9
   | NonceOverflow => 10
   | AddressCollision => 11
   end.

Definition ExceptionKind_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 11)*) : ExceptionKind :=
   let l__0 := arg_ in
   if Z.eqb (l__0) (0) then StackUnderflow
   else if Z.eqb (l__0) (1) then StackOverflow
   else if Z.eqb (l__0) (2) then OutOfGas
   else if Z.eqb (l__0) (3) then InvalidOpcode
   else if Z.eqb (l__0) (4) then InvalidJump
   else if Z.eqb (l__0) (5) then StaticViolation
   else if Z.eqb (l__0) (6) then CallDepthExceeded
   else if Z.eqb (l__0) (7) then InsufficientBalance
   else if Z.eqb (l__0) (8) then WriteProtection
   else if Z.eqb (l__0) (9) then InitCodeTooLarge
   else if Z.eqb (l__0) (10) then NonceOverflow
   else AddressCollision.

Lemma ExceptionKind_num_of_roundtrip (x : ExceptionKind) : ExceptionKind_of_num (num_of_ExceptionKind x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_ExceptionKind_injective (x y : ExceptionKind) : num_of_ExceptionKind x = num_of_ExceptionKind y -> x = y.
  intro.
  rewrite <- (ExceptionKind_num_of_roundtrip x).
  rewrite <- (ExceptionKind_num_of_roundtrip y).
  congruence.
Qed.
Definition ExceptionKind_eq_dec (x y : ExceptionKind) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_ExceptionKind x) (num_of_ExceptionKind y) with
  | left e => left (num_of_ExceptionKind_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition ExceptionKind_beq (x y : ExceptionKind) : bool :=
  Z.eqb (num_of_ExceptionKind x) (num_of_ExceptionKind y).
Lemma ExceptionKind_beq_iff x y : ExceptionKind_beq x y = true <-> x = y.
  unfold ExceptionKind_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_ExceptionKind_injective | congruence].
Qed.
Lemma ExceptionKind_beq_refl x : ExceptionKind_beq x x = true.
apply ExceptionKind_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_ExceptionKind : EqDecision ExceptionKind := ExceptionKind_eq_dec.
#[export]
Instance Countable_ExceptionKind : Countable ExceptionKind.
refine {|
  encode x := encode (num_of_ExceptionKind x);
  decode x := z ← decode x; mret (ExceptionKind_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite ExceptionKind_num_of_roundtrip;
  reflexivity).
Defined.
#[export]
Instance dummy_ExceptionKind : Inhabited ExceptionKind := { inhabitant := StackUnderflow }.


Inductive BlockError :=
  | InvalidConfig
  | HeaderChainBroken
  | RlpDecode
  | InvalidSignature
  | InvalidGasLimit
  | GasUsedExceedsLimit
  | BlobGasLimitExceeded
  | ExecutionInvalid
  | InvalidGasUsed
  | InvalidBlobGasUsed
  | InvalidExcessBlobGas
  | InvalidStateRoot
  | InvalidReceiptsRoot
  | InvalidLogsBloom
  | InvalidBlockHash
  | InvalidParentHash
  | BlockAccessListTooLarge
  | InvalidBlockAccessList
  | InvalidExecutionRequests
  | WitnessDeficient.
Definition num_of_BlockError (arg_ : BlockError) : Z :=
   match arg_ with
   | InvalidConfig => 0
   | HeaderChainBroken => 1
   | RlpDecode => 2
   | InvalidSignature => 3
   | InvalidGasLimit => 4
   | GasUsedExceedsLimit => 5
   | BlobGasLimitExceeded => 6
   | ExecutionInvalid => 7
   | InvalidGasUsed => 8
   | InvalidBlobGasUsed => 9
   | InvalidExcessBlobGas => 10
   | InvalidStateRoot => 11
   | InvalidReceiptsRoot => 12
   | InvalidLogsBloom => 13
   | InvalidBlockHash => 14
   | InvalidParentHash => 15
   | BlockAccessListTooLarge => 16
   | InvalidBlockAccessList => 17
   | InvalidExecutionRequests => 18
   | WitnessDeficient => 19
   end.

Definition BlockError_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 19)*) : BlockError :=
   let l__0 := arg_ in
   if Z.eqb (l__0) (0) then InvalidConfig
   else if Z.eqb (l__0) (1) then HeaderChainBroken
   else if Z.eqb (l__0) (2) then RlpDecode
   else if Z.eqb (l__0) (3) then InvalidSignature
   else if Z.eqb (l__0) (4) then InvalidGasLimit
   else if Z.eqb (l__0) (5) then GasUsedExceedsLimit
   else if Z.eqb (l__0) (6) then BlobGasLimitExceeded
   else if Z.eqb (l__0) (7) then ExecutionInvalid
   else if Z.eqb (l__0) (8) then InvalidGasUsed
   else if Z.eqb (l__0) (9) then InvalidBlobGasUsed
   else if Z.eqb (l__0) (10) then InvalidExcessBlobGas
   else if Z.eqb (l__0) (11) then InvalidStateRoot
   else if Z.eqb (l__0) (12) then InvalidReceiptsRoot
   else if Z.eqb (l__0) (13) then InvalidLogsBloom
   else if Z.eqb (l__0) (14) then InvalidBlockHash
   else if Z.eqb (l__0) (15) then InvalidParentHash
   else if Z.eqb (l__0) (16) then BlockAccessListTooLarge
   else if Z.eqb (l__0) (17) then InvalidBlockAccessList
   else if Z.eqb (l__0) (18) then InvalidExecutionRequests
   else WitnessDeficient.

Lemma BlockError_num_of_roundtrip (x : BlockError) : BlockError_of_num (num_of_BlockError x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_BlockError_injective (x y : BlockError) : num_of_BlockError x = num_of_BlockError y -> x = y.
  intro.
  rewrite <- (BlockError_num_of_roundtrip x).
  rewrite <- (BlockError_num_of_roundtrip y).
  congruence.
Qed.
Definition BlockError_eq_dec (x y : BlockError) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_BlockError x) (num_of_BlockError y) with
  | left e => left (num_of_BlockError_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition BlockError_beq (x y : BlockError) : bool :=
  Z.eqb (num_of_BlockError x) (num_of_BlockError y).
Lemma BlockError_beq_iff x y : BlockError_beq x y = true <-> x = y.
  unfold BlockError_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_BlockError_injective | congruence].
Qed.
Lemma BlockError_beq_refl x : BlockError_beq x x = true.
apply BlockError_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_BlockError : EqDecision BlockError := BlockError_eq_dec.
#[export]
Instance Countable_BlockError : Countable BlockError.
refine {|
  encode x := encode (num_of_BlockError x);
  decode x := z ← decode x; mret (BlockError_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite BlockError_num_of_roundtrip;
  reflexivity).
Defined.
#[export]
Instance dummy_BlockError : Inhabited BlockError := { inhabitant := InvalidConfig }.


Inductive exception :=
| InvalidBlock : BlockError -> exception.
Arguments exception : clear implicits.

Definition sail_exception_encode (x : exception) := match x with
  | InvalidBlock x' => encode (0, encode x') end.
Definition sail_exception_decode x : option exception := match decode x with
  | Some (0, x') => InvalidBlock <$> decode x'
  | _ => None end.
Lemma sail_exception_decode_encode : forall (x : exception), sail_exception_decode
  (sail_exception_encode x)  = Some x.
Proof.
  unfold sail_exception_decode, sail_exception_encode;
  intros [x]; rewrite !decode_encode; reflexivity.
Qed.

#[export]
Instance Decidable_eq_exception : EqDecision exception := decode_encode_eq_dec sail_exception_encode
  sail_exception_decode sail_exception_decode_encode .

#[export]
Instance Countable_exception : Countable exception := {|
  encode := sail_exception_encode;
  decode := sail_exception_decode;
  decode_encode := sail_exception_decode_encode
|}.
#[export]
Instance dummy_exception : Inhabited (exception) := { inhabitant := InvalidBlock inhabitant }.

