Inductive StateCheckpoint_typ :=
| StateCheckpoint : protocol_quantity -> StateCheckpoint_typ.
Arguments StateCheckpoint_typ : clear implicits.

Definition sail_StateCheckpoint_typ_encode (x : StateCheckpoint_typ) := match x with
  | StateCheckpoint x' => encode (0, encode x') end.
Definition sail_StateCheckpoint_typ_decode x : option StateCheckpoint_typ := match decode x with
  | Some (0, x') => StateCheckpoint <$> decode x'
  | _ => None end.
Lemma sail_StateCheckpoint_typ_decode_encode : forall (x : StateCheckpoint_typ),
  sail_StateCheckpoint_typ_decode (sail_StateCheckpoint_typ_encode x)  = Some x.
Proof.
  unfold sail_StateCheckpoint_typ_decode, sail_StateCheckpoint_typ_encode;
  intros [x]; rewrite !decode_encode; reflexivity.
Qed.

#[export]
Instance Decidable_eq_StateCheckpoint_typ : EqDecision StateCheckpoint_typ := decode_encode_eq_dec
  sail_StateCheckpoint_typ_encode sail_StateCheckpoint_typ_decode
  sail_StateCheckpoint_typ_decode_encode .

#[export]
Instance Countable_StateCheckpoint_typ : Countable StateCheckpoint_typ := {|
  encode := sail_StateCheckpoint_typ_encode;
  decode := sail_StateCheckpoint_typ_decode;
  decode_encode := sail_StateCheckpoint_typ_decode_encode
|}.
#[export]
Instance dummy_StateCheckpoint_typ : Inhabited (StateCheckpoint_typ) := {
  inhabitant := StateCheckpoint inhabitant
}.

Inductive TxType := LegacyTx | AccessListTx | FeeMarketTx | BlobTx | SetCodeTx.
Definition num_of_TxType (arg_ : TxType) : Z :=
   match arg_ with
   | LegacyTx => 0
   | AccessListTx => 1
   | FeeMarketTx => 2
   | BlobTx => 3
   | SetCodeTx => 4
   end.

Definition TxType_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 4)*) : TxType :=
   let l__0 := arg_ in
   if Z.eqb (l__0) (0) then LegacyTx
   else if Z.eqb (l__0) (1) then AccessListTx
   else if Z.eqb (l__0) (2) then FeeMarketTx
   else if Z.eqb (l__0) (3) then BlobTx
   else SetCodeTx.

Lemma TxType_num_of_roundtrip (x : TxType) : TxType_of_num (num_of_TxType x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_TxType_injective (x y : TxType) : num_of_TxType x = num_of_TxType y -> x = y.
  intro.
  rewrite <- (TxType_num_of_roundtrip x).
  rewrite <- (TxType_num_of_roundtrip y).
  congruence.
Qed.
Definition TxType_eq_dec (x y : TxType) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_TxType x) (num_of_TxType y) with
  | left e => left (num_of_TxType_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition TxType_beq (x y : TxType) : bool :=
  Z.eqb (num_of_TxType x) (num_of_TxType y).
Lemma TxType_beq_iff x y : TxType_beq x y = true <-> x = y.
  unfold TxType_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_TxType_injective | congruence].
Qed.
Lemma TxType_beq_refl x : TxType_beq x x = true.
apply TxType_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_TxType : EqDecision TxType := TxType_eq_dec.
#[export]
Instance Countable_TxType : Countable TxType.
refine {|
  encode x := encode (num_of_TxType x);
  decode x := z ← decode x; mret (TxType_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite TxType_num_of_roundtrip;
  reflexivity).
Defined.
#[export]
Instance dummy_TxType : Inhabited TxType := { inhabitant := LegacyTx }.


