  | Some (7, x') => SMOD <$> decode x'
  | Some (8, x') => ADDMOD <$> decode x'
  | Some (9, x') => MULMOD <$> decode x'
  | Some (10, x') => EXP <$> decode x'
  | Some (11, x') => SIGNEXTEND <$> decode x'
  | Some (12, x') => LT' <$> decode x'
  | Some (13, x') => GT' <$> decode x'
  | Some (14, x') => SLT <$> decode x'
  | Some (15, x') => SGT <$> decode x'
  | Some (16, x') => EQ' <$> decode x'
  | Some (17, x') => ISZERO <$> decode x'
  | Some (18, x') => AND <$> decode x'
  | Some (19, x') => OR <$> decode x'
  | Some (20, x') => XOR <$> decode x'
  | Some (21, x') => NOT <$> decode x'
  | Some (22, x') => BYTE <$> decode x'
  | Some (23, x') => SHL <$> decode x'
  | Some (24, x') => SHR <$> decode x'
  | Some (25, x') => SAR <$> decode x'
  | Some (26, x') => CLZ <$> decode x'
