  | Some (47, x') => NUMBER <$> decode x'
  | Some (48, x') => PREVRANDAO <$> decode x'
  | Some (49, x') => GASLIMIT <$> decode x'
  | Some (50, x') => CHAINID <$> decode x'
  | Some (51, x') => SELFBALANCE <$> decode x'
  | Some (52, x') => BASEFEE <$> decode x'
  | Some (53, x') => BLOBHASH <$> decode x'
  | Some (54, x') => BLOBBASEFEE <$> decode x'
  | Some (55, x') => SLOTNUM <$> decode x'
  | Some (56, x') => POP <$> decode x'
  | Some (57, x') => MLOAD <$> decode x'
  | Some (58, x') => MSTORE <$> decode x'
  | Some (59, x') => MSTORE8 <$> decode x'
  | Some (60, x') => SLOAD <$> decode x'
  | Some (61, x') => SSTORE <$> decode x'
  | Some (62, x') => JUMP <$> decode x'
  | Some (63, x') => JUMPI <$> decode x'
  | Some (64, x') => PC <$> decode x'
  | Some (65, x') => MSIZE <$> decode x'
  | Some (66, x') => GAS <$> decode x'
  | Some (67, x') => JUMPDEST <$> decode x'
  | Some (68, x') => TLOAD <$> decode x'
  | Some (69, x') => TSTORE <$> decode x'
  | Some (70, x') => MCOPY <$> decode x'
  | Some (71, x') => PUSH <$> decode x'
  | Some (72, x') => DUP <$> decode x'
  | Some (73, x') => SWAP <$> decode x'
  | Some (74, x') => LOG <$> decode x'
  | Some (75, x') => CREATE <$> decode x'
  | Some (76, x') => CALL <$> decode x'
  | Some (77, x') => CALLCODE <$> decode x'
  | Some (78, x') => RETURN <$> decode x'
  | Some (79, x') => DELEGATECALL <$> decode x'
  | Some (80, x') => CREATE2 <$> decode x'
  | Some (81, x') => STATICCALL <$> decode x'
  | Some (82, x') => REVERT <$> decode x'
  | Some (83, x') => INVALID <$> decode x'
  | Some (84, x') => SELFDESTRUCT <$> decode x'
  | _ => None end.
Lemma sail_ast_decode_encode : forall (x : ast), sail_ast_decode (sail_ast_encode x)  = Some x.
Proof.
  unfold sail_ast_decode, sail_ast_encode;
  intros [x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x]; rewrite !decode_encode; reflexivity.
Qed.

#[export]
Instance Decidable_eq_ast : EqDecision ast := decode_encode_eq_dec sail_ast_encode sail_ast_decode
  sail_ast_decode_encode .

#[export]
Instance Countable_ast : Countable ast := {|
  encode := sail_ast_encode;
  decode := sail_ast_decode;
  decode_encode := sail_ast_decode_encode
|}.
#[export]
Instance dummy_ast : Inhabited (ast) := { inhabitant := STOP inhabitant }.

